import{_ as t,o,c as d,a2 as a}from"./chunks/framework.7nMnW4XS.js";const g=JSON.parse('{"title":"Orrery tooling reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tooling/README.md","filePath":"reference/tooling/README.md"}'),i={name:"reference/tooling/README.md"};function r(n,e,s,c,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="orrery-tooling-reference" tabindex="-1">Orrery tooling reference <a class="header-anchor" href="#orrery-tooling-reference" aria-label="Permalink to &quot;Orrery tooling reference&quot;">​</a></h1><p>The canonical map of Orrery&#39;s <strong>standing tools</strong> — the scripts and <code>npm run</code> targets you actually invoke (build, validate, fetch, generate, deploy). It exists because <code>scripts/</code> had grown to ~260 files and the ~60 durable tools were buried under ~165 one-shot wave/slice/migration scripts (now in <a href="./archive"><code>scripts/_archive/</code></a>).</p><p>This is an <strong>index</strong>: each category page lists tools with <em>what / when / gotchas / state</em>, and links to the deep references rather than duplicating them. The deep references remain authoritative for end-to-end flow:</p><ul><li><strong><a href="./../../adr/TA"><code>docs/adr/TA.md</code> §pipelines</a></strong> — the 10 numbered build-time pipelines.</li><li><strong><a href="./../../../scripts/IMAGE-PIPELINE"><code>scripts/IMAGE-PIPELINE.md</code></a></strong> — full image pipeline (source order, worked example).</li><li><strong><a href="./../../guides/image-pipeline-v2"><code>docs/guides/image-pipeline-v2.md</code></a></strong>, <strong><a href="./../../guides/audio-pipeline-setup"><code>docs/guides/audio-pipeline-setup.md</code></a></strong>, <strong><a href="./../../anatomy-art-runbook"><code>docs/anatomy-art-runbook.md</code></a></strong> — operator runbooks.</li></ul><h2 id="category-pages" tabindex="-1">Category pages <a class="header-anchor" href="#category-pages" aria-label="Permalink to &quot;Category pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Covers</th></tr></thead><tbody><tr><td><a href="./build-ci-deploy">build-ci-deploy.md</a></td><td><code>build</code> / <code>preflight</code> / <code>lint</code> / <code>typecheck</code> / <code>test</code>, screenshots, secret scans, docker, the deploy + release workflows</td></tr><tr><td><a href="./data-validation">data-validation.md</a></td><td><code>validate-data</code> orchestrator + every validator gate + the on-demand <code>audit:*</code> family</td></tr><tr><td><a href="./image-pipeline">image-pipeline.md</a></td><td><code>fetch-assets</code> → <code>score-images</code> → <code>/dev/staging</code> → <code>build-image-provenance</code>, hotspots, hero/dedup maintenance, <code>scripts/lib/</code></td></tr><tr><td><a href="./content-pipelines">content-pipelines.md</a></td><td>i18n (<code>wave23</code> + paraglide), audio, links, launches, science index, porkchops, tech-BOM, cislunar</td></tr><tr><td><a href="./archive">archive.md</a></td><td>the 135 retired one-shot scripts + why</td></tr></tbody></table><h2 id="when-to-reach-for-what-quick-index" tabindex="-1">When to reach for what (quick index) <a class="header-anchor" href="#when-to-reach-for-what-quick-index" aria-label="Permalink to &quot;When to reach for what (quick index)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to…</th><th>Run</th><th>Page</th></tr></thead><tbody><tr><td>Verify before pushing</td><td><code>npm run preflight</code></td><td><a href="./build-ci-deploy">build-ci-deploy</a></td></tr><tr><td>Check JSON data is valid + complete</td><td><code>npm run validate-data</code></td><td><a href="./data-validation">data-validation</a></td></tr><tr><td>Prove every shipped image is used</td><td><code>npm run audit:images</code></td><td><a href="./data-validation">data-validation</a></td></tr><tr><td>Fetch new imagery for an entity</td><td><code>npm run fetch-assets</code> (stages to <code>_staging/</code>)</td><td><a href="./image-pipeline">image-pipeline</a></td></tr><tr><td>Score fetched images</td><td><code>npm run images:score</code></td><td><a href="./image-pipeline">image-pipeline</a></td></tr><tr><td>Review + promote staged images</td><td><code>/dev/staging</code> (dev route)</td><td><a href="./image-pipeline">image-pipeline</a></td></tr><tr><td>Re-credit after promoting</td><td><code>npm run build-image-provenance -- --offline</code></td><td><a href="./image-pipeline">image-pipeline</a></td></tr><tr><td>Add surface (Mars/Moon) detail imagery</td><td><code>npm run images:hotspots</code> (Node 20 + gdal)</td><td><a href="./image-pipeline">image-pipeline</a></td></tr><tr><td>Compile messages for dev/build</td><td><code>npm run i18n:compile</code></td><td><a href="./content-pipelines">content-pipelines</a></td></tr><tr><td>Translate to all 14 locales</td><td><code>scripts/wave23/</code> toolchain</td><td><a href="./content-pipelines">content-pipelines</a></td></tr><tr><td>Generate narration audio</td><td><code>npm run audio:generate -- --episode &lt;id&gt;</code></td><td><a href="./content-pipelines">content-pipelines</a></td></tr><tr><td>Validate outbound LEARN links</td><td><code>npm run check-learn-links</code></td><td><a href="./content-pipelines">content-pipelines</a></td></tr><tr><td>Refresh the launches manifest</td><td><code>npm run fetch:launches</code></td><td><a href="./content-pipelines">content-pipelines</a></td></tr><tr><td>Deploy to prod</td><td>trigger <strong>Deploy to prod VPS</strong> workflow</td><td><a href="./build-ci-deploy">build-ci-deploy</a></td></tr></tbody></table><h2 id="state-opportunities-assessed-2026-06-28" tabindex="-1">State &amp; opportunities (assessed 2026-06-28) <a class="header-anchor" href="#state-opportunities-assessed-2026-06-28" aria-label="Permalink to &quot;State &amp; opportunities (assessed 2026-06-28)&quot;">​</a></h2><p><strong>Overall: healthy.</strong> The durable surface is small, mostly npm-wired, and gated by <code>preflight</code> + <code>validate-data</code>. The pipelines (fetch, provenance, validation, audio, i18n, deploy) are all current and exercised by CI/docker-e2e.</p><p>What this audit changed:</p><ul><li><strong>Resolved the one-shot sprawl.</strong> 135 dead one-shots moved to <a href="./archive"><code>scripts/_archive/</code></a>; <code>scripts/</code> now reflects only standing tools. ESLint / Prettier / tsconfig exclude the archive.</li><li><strong>Fixed a broken standing tool.</strong> <code>scripts/release-rehearsal.ts</code> redeclared <code>const changelogPath</code> at module scope (TS2451) — <code>npm run release:rehearsal</code> would have thrown at parse. <code>scripts/</code> is outside the tsconfig include, so <code>npm run typecheck</code> never caught it. De-duped this session.</li></ul><p>Opportunities worth a future slice (none blocking):</p><ol><li><strong><code>scripts/</code> isn&#39;t typechecked.</strong> The TS2451 above slipped through because the tsconfig include is src-focused; standing <code>scripts/*.ts</code> get type-checked only when something imports them or when <code>tsx</code> runs them. Worth a <code>tsconfig.scripts.json</code><ul><li>a <code>typecheck:scripts</code> step so tool bugs fail closed in CI.</li></ul></li><li><strong>Promote audits into gates.</strong> <code>npm run audit:images</code> is the strongest candidate — it already exits 1 on orphans and knows all ~11 gallery manifests, vs the 2 that <code>validate-gallery-counts</code> gates. Folding it (and <code>audit-image-mime</code>, already inline) into <code>validate-data</code> makes image-orphan regressions fail closed. Coverage is a one-way ratchet (AGENTS.md).</li><li><strong>Overlapping/disk-mutating audits.</strong> <code>audit-fleet-heroes.ts</code> <em>mutates disk</em> (auto-swaps slots + rewrites the sidecar) and overlaps the newer read-only <code>audit-heroes.ts</code> — retirement / merge candidate. Audit tools should default to read-only with an explicit <code>--repair</code>.</li><li><strong>Small consolidations.</strong> <code>check</code> and <code>typecheck</code> are byte-identical npm scripts; <code>gh-pages-compat.mjs</code> hand-mirrors the locale list from <code>project.inlang/settings.json</code> (drift hazard — derive it).</li><li><strong>Stub commands exit 2.</strong> <code>npm run audio:translate</code> and <code>audio:build</code> are not-implemented stubs (deferred to v0.8 / #152). Fine, but document/track so nobody wires them into a pipeline expecting output.</li><li><strong>Discoverability + headers.</strong> Many standing tools aren&#39;t npm-aliased (<code>compute-phash</code>, <code>generate-hero-overrides</code>, <code>prune-orphan-images</code>) — run via <code>npx tsx scripts/&lt;name&gt;.ts</code>. Alias the frequently-used ones, and give every <em>standing</em> script a one-line header (purpose + alias) so this index can be regenerated mechanically — most archived one-shots had none.</li><li><strong><code>hotspots/</code> has its own one-shots.</strong> <code>backfill-imagery-provenance.ts</code>, <code>reupsert-tier2-provenance.ts</code> are one-shot backfills left in place because the subdir is a cohesive unit; a future pass could split <code>hotspots/_archive/</code>.</li><li><strong>Fetch-script pattern.</strong> The archived <code>fetch-batch-*</code> / <code>fetch-tier-*</code> / <code>handsource-*</code> sprawl shows the recurring need was always &quot;source images for a named set of entities.&quot; The standing answer is <code>fetch-assets</code> + <code>source-known-gaps</code> + <code>fill-gallery-gaps</code>; extend those with an <code>--entities &lt;list&gt;</code> input rather than writing another per-batch script.</li></ol><p>Keeping this index honest: when you add a standing tool, add a row to the right category page; when you retire one, move it to <code>_archive/</code> and note it in <a href="./archive">archive.md</a>.</p>',15)])])}const u=t(i,[["render",r]]);export{g as __pageData,u as default};
